pub(crate) fn react_augmentations(&self, react_file: &Utf8Path, qualified: &str) -> Vec<&CollectedInterface> {
    let places = self.cached_augmentation(
        |state| state.places.get(react_file.as_str())?.get(qualified).cloned(),
        || {
            let react_key = PathKey::from(react_file);
            let mut found: Vec<(&CollectedInterface, usize, &PathKey)> = Vec::new();
            let mut layer = Some(self);
            let mut depth = 0;
            while let Some(index) = layer {
                for file in index.react_namespaced.iter().filter(|file| **file != react_key) {
                    if let Some(iface) = index.interfaces.get(file).and_then(|per_file| per_file.get(qualified)) {
                        found.push((iface, depth, file));
                    }
                }
                layer = index.fallback.as_deref();
                depth += 1;
            }
            found.sort_by(|a, b| a.0.file_path.cmp(&b.0.file_path));
            found.into_iter().map(|(_, depth, file)| (depth, file.clone())).collect()
        },
        |state, places: &std::sync::Arc<[(usize, PathKey)]>| {
            state.places.entry(Box::from(react_file.as_str())).or_default().insert(Box::from(qualified), places.clone());
        },
    );
    places
        .iter()
        .filter_map(|(depth, file)| {
            let mut index = self;
            for _ in 0..*depth {
                index = index.fallback.as_deref()?;
            }
            index.interfaces.get(file)?.get(qualified)
        })
        .collect()
}

/// The files other than `react_file` that declare into the `React` namespace in any layer, which is every file
/// `react_augmentations` can read from. A resolution that reads augmentations depends on each.
pub(crate) fn react_augmenting_files(&self, react_file: &Utf8Path) -> std::sync::Arc<[PathKey]> {
    self.cached_augmentation(
        |state| state.files.get(react_file.as_str()).cloned(),
        || {
            let react_key = PathKey::from(react_file);
            let mut files = Vec::new();
            let mut layer = Some(self);
            while let Some(index) = layer {
                files.extend(index.react_namespaced.iter().filter(|file| **file != react_key).cloned());
                layer = index.fallback.as_deref();
            }
            files.into()
        },
        |state, files| {
            state.files.insert(Box::from(react_file.as_str()), files.clone());
        },
    )
}

/// An answer from the augmentation cache, computing and keeping it when this index has not given it yet. The
/// cache is dropped first if `fallback` is not the one its answers were computed over.
fn cached_augmentation<T: Clone>(
    &self,
    read: impl FnOnce(&AugmentationState) -> Option<T>,
    compute: impl FnOnce() -> T,
    keep: impl FnOnce(&mut AugmentationState, &T),
) -> T {
    let stamp = self.fallback.as_ref().map_or(0, |fallback| std::sync::Arc::as_ptr(fallback) as usize);
    if let Ok(state) = self.augmentations.0.read()
        && state.stamp == stamp
        && let Some(answer) = read(&state)
    {
        return answer;
    }
    let answer = compute();
    let mut state = self.augmentations.0.write().unwrap_or_else(std::sync::PoisonError::into_inner);
    if state.stamp != stamp {
        *state = AugmentationState { stamp, ..AugmentationState::default() };
    }
    keep(&mut state, &answer);
    answer
}

