/// An answer from the augmentation cache, computing and keeping it when this index has not given it yet. The
/// cache is dropped first if `fallback` is not the one its answers were computed over.
fn cached_augmentation<T: Clone>(
    &self,
    read: impl FnOnce(&AugmentationState) -> Option<T>,
    compute: impl FnOnce() -> T,
    keep: impl FnOnce(&mut AugmentationState, &T),
) -> T {
    let stamp = self.fallback.as_ref().map_or(0, |fallback| std::sync::Arc::as_ptr(fallback) as usize);
    if let Ok(state) = self.augmentations.0.read()
        && state.stamp == stamp
        && let Some(answer) = read(&state)
    {
        return answer;
    }
    let answer = compute();
    let mut state = self.augmentations.0.write().unwrap_or_else(std::sync::PoisonError::into_inner);
    if state.stamp != stamp {
        *state = AugmentationState { stamp, ..AugmentationState::default() };
    }
    keep(&mut state, &answer);
    answer
}

