    let t = std::time::Instant::now();
    note_augmentations(react_file, ctx);
    let mut layers: Vec<&CollectedInterface> =
        ctx.react_index().lookup_interface_exact(react_file, key).into_iter().collect();
    layers.extend(ctx.named_types.react_augmentations(react_file, key));
    static NS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    static N: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let ns = NS.fetch_add(t.elapsed().as_nanos() as u64, std::sync::atomic::Ordering::Relaxed);
    let n = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if n % 20000 == 19999 {
        eprintln!("PROFILE merged_interfaces calls={} ms={}", n + 1, ns as f64 / 1e6);
    }
    layers
}

