419	    /// Resolve `specifier` as imported by `from_file`, the way the resolver will.
420	    fn resolve(&self, from_file: &Utf8Path, specifier: &str) -> Result<Utf8PathBuf, Unresolved> {
421	        let dir = from_file.parent().map_or("", Utf8Path::as_str);
422	        let key = (Box::from(dir), Box::from(specifier));
423	        if let Some(found) = self.resolutions.get(&key) {
424	            return found.clone();
425	        }
426	        if let Some(found) = self.parent.and_then(|parent| parent.resolution(&key)) {
427	            return found.clone();
428	        }
429	        let result = match crate::resolver::resolve_module_with(
430	            &self.resolvers.main,
431	            &self.resolvers.types_first,
432	            specifier,
433	            from_file,
434	        ) {
435	            ModuleResolution::PackageTypes(path) => Ok(path),
436	            ModuleResolution::File(path) if is_typescript(&path) => Ok(path),
437	            ModuleResolution::File(_) => Err(Unresolved::NoTypes),
438	            ModuleResolution::Unresolved(_) => Err(Unresolved::Unresolvable),
439	        };
440	        self.learn(Utf8Path::new(dir));
441	        self.resolutions.insert(key, result.clone());
442	        result
443	    }
