449	    /// React's own types stay with the resolver's React handling (builtins, curated HTML attributes).
450	    fn is_react(file: &Utf8Path) -> bool {
451	        let path = file.as_str();
452	        path.contains("/node_modules/@types/react/") || path.contains("/node_modules/react/")
453	    }
