455	    /// The `(file, name)` declaring `name` as exported from `module`.
456	    fn find_export(&self, module: &Utf8Path, name: &str) -> Option<(Utf8PathBuf, CompactString)> {
457	        self.find_export_in(module, name, &mut FxHashSet::default(), &mut false)
458	    }
459	
460	    /// `find_export` within one walk. A lookup that met a module already on the walk (a re-export cycle) is `cut`: its
461	    /// answer depends on where the walk entered the cycle, so it is returned but not kept, and the cut propagates to
462	    /// every lookup that relied on it. Kept answers are therefore the same in any order and on any thread.
463	    fn find_export_in(
464	        &self,
465	        module: &Utf8Path,
466	        name: &str,
467	        visited: &mut FxHashSet<(PathKey, CompactString)>,
468	        cut: &mut bool,
469	    ) -> Option<(Utf8PathBuf, CompactString)> {
470	        let key = (PathKey::from(module), CompactString::from(name));
471	        if let Some(found) = self.exports.get(&key) {
472	            return found.clone();
473	        }
474	        if let Some(found) = self.parent.and_then(|parent| parent.export_entry(&key)) {
475	            return found.clone();
476	        }
477	        if !visited.insert(key.clone()) {
478	            *cut = true;
479	            return None;
480	        }
481	        let mut own_cut = false;
482	        let found = self.find_export_uncached(module, name, visited, &mut own_cut);
483	        visited.remove(&key);
484	        if own_cut {
485	            *cut = true;
486	        } else {
487	            if let Some(dir) = module.parent() {
488	                self.learn(dir);
489	            }
490	            self.exports.insert(key, found.clone());
491	        }
492	        found
493	    }
494	
495	    fn find_export_uncached(
496	        &self,
497	        module: &Utf8Path,
498	        name: &str,
499	        visited: &mut FxHashSet<(PathKey, CompactString)>,
500	        cut: &mut bool,
501	    ) -> Option<(Utf8PathBuf, CompactString)> {
502	        let data = self.parse(module)?;
503	        if declares(&data, module, name) {
504	            return Some((module.to_owned(), CompactString::from(name)));
505	        }
506	        // A member of a value the module declares (`Primitive.div`): its declaration is the value's.
507	        if name.split_once('.').is_some_and(|(head, _)| declares(&data, module, head)) {
508	            return Some((module.to_owned(), CompactString::from(name)));
509	        }
510	        let (head, rest) = match name.split_once('.') {
511	            Some((head, rest)) => (head, Some(rest)),
512	            None => (name, None),
513	        };
514	        for export in &data.exports {
515	            match export {
516	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } if local_name == head => {
517	                    let target = self.resolve(module, source_specifier).ok()?;
518	                    let next = match rest {
519	                        Some(rest) => format!("{source_name}.{rest}"),
520	                        None => source_name.clone(),
521	                    };
522	                    return self.find_export_in(&target, &next, visited, cut);
523	                }
524	                LexedExport::ReExportNamespace { namespace, source_specifier } if namespace == head => {
525	                    let target = self.resolve(module, source_specifier).ok()?;
526	                    return self.find_export_in(&target, rest?, visited, cut);
527	                }
528	                // `export { DialogContent as Content }`, the way bundled typings (Radix's) name their parts.
529	                LexedExport::LocalDeclaration { name: exported, declared_as: Some(local), .. }
530	                    if exported == head && declares(&data, module, local) =>
531	                {
532	                    let name = match rest {
533	                        Some(rest) => format!("{local}.{rest}"),
534	                        None => local.clone(),
535	                    };
536	                    return Some((module.to_owned(), CompactString::from(name)));
537	                }
538	                _ => {}
539	            }
540	        }
541	        // A local export can name an imported binding (`import Image from './Image'; export default Image`).
542	        if let Some(local) = data.exports.iter().find_map(|export| match export {
543	            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == head => {
544	                Some(declared_as.as_deref().unwrap_or(head))
545	            }
546	            LexedExport::LocalDeclaration { .. }
547	            | LexedExport::ReExportNamed { .. }
548	            | LexedExport::ReExportAll { .. }
549	            | LexedExport::ReExportNamespace { .. } => None,
550	        }) {
551	            let reference = rest.map_or_else(|| local.to_owned(), |rest| format!("{local}.{rest}"));
552	            if let Some(demand) = imported_demand(module, &data.imports, &reference) {
553	                let target = self.resolve(module, &demand.specifier).ok()?;
554	                return self.find_export_in(&target, &demand.name, visited, cut);
555	            }
556	        }
557	        if head == "default" {
558	            return None;
559	        }
560	        for export in &data.exports {
561	            if let LexedExport::ReExportAll { source_specifier, .. } = export {
562	                let Ok(target) = self.resolve(module, source_specifier) else { continue };
563	                if let Some(found) = self.find_export_in(&target, name, visited, cut) {
564	                    return Some(found);
565	                }
566	            }
567	        }
568	        None
569	    }
