571	    fn demand<'s>(&'s self, scope: &rayon::Scope<'s>, demand: Demand) {
572	        let key = demand.key();
573	        if self.parent.is_some_and(|parent| parent.has_demand(&key)) || !self.demands.insert(key.clone()) {
574	            return;
575	        }
576	        let module = match self.resolve(&demand.from, &demand.specifier) {
577	            Ok(module) => module,
578	            Err(reason) => {
579	                if !demand.name.is_empty() {
580	                    self.unresolved.insert(key, reason);
581	                }
582	                return;
583	            }
584	        };
585	        if self.in_project(&module) {
586	            return;
587	        }
588	        // A module imported for its own sake: only what it merges into React is read.
589	        if demand.name.is_empty() {
590	            if !Self::is_react(&module) {
591	                self.load_augmentations(scope, &module);
592	            }
593	            return;
594	        }
595	        if Self::is_react(&module) {
596	            // `@types/react` declares its exports inside `declare namespace React` (`export = React`).
597	            let qualified = CompactString::from(format!("React.{}", demand.name));
598	            if self.parse(&module).is_some_and(|data| declares(&data, &module, &qualified)) {
599	                self.load_declaration(scope, module, qualified);
600	            }
601	            return;
602	        }
603	        match self.find_export(&module, &demand.name) {
604	            Some((file, name)) => self.load_declaration(scope, file, name),
605	            None => {
606	                self.unresolved.insert(key, Unresolved::NotExported);
607	            }
608	        }
609	    }
