611	    /// Load the files `module` leads to through its re-exports that merge declarations into React
612	    /// (`declare module "react" { ... }`): TypeScript reads them whenever the program reaches the file, whether or not
613	    /// a name from them is used. The search is bounded ([`AUGMENTATION_SCAN_FILES`]), breadth first in source order,
614	    /// so the answer for a module is the same on any thread; it is kept, in the layer and in the index on disk.
615	    fn load_augmentations<'s>(&'s self, scope: &rayon::Scope<'s>, module: &Utf8Path) {
616	        let key = PathKey::from(module);
617	        let known = self.augmenters.get(&key).map(|files| files.clone());
618	        let known = known.or_else(|| self.parent.and_then(|parent| parent.augmenters_of(&key)).cloned());
619	        let files = known.unwrap_or_else(|| {
620	            let (files, crossed) = self.find_augmenting_files(module);
621	            self.augmenters.insert(key.clone(), files.clone());
622	            self.augmenter_crossed.insert(key, crossed);
623	            // An empty answer is persisted too, or the next run would scan the module's re-exports again.
624	            module.parent().inspect(|dir| self.learn(dir));
625	            files
626	        });
627	        for file in files {
628	            let Some(data) = self.parse(&file) else { continue };
629	            let mut names: Vec<&String> = data.interfaces.keys().collect();
630	            names.sort();
631	            for key in names {
632	                if let Some(name) = key.strip_prefix(file.as_str()).and_then(|rest| rest.strip_prefix(':')) {
633	                    if name.starts_with("React.") {
634	                        self.load_declaration(scope, file.clone(), CompactString::from(name));
635	                    }
636	                }
637	            }
638	        }
639	    }
