641	    /// The files `module`'s re-exports lead to that augment React, and the stamps of the other packages the search read
642	    /// files from: the answer holds only while those packages do not change, as well as the module's own.
643	    fn find_augmenting_files(&self, module: &Utf8Path) -> (Vec<Utf8PathBuf>, Vec<PackageStampRow>) {
644	        let mut found = Vec::new();
645	        let mut seen: FxHashSet<Utf8PathBuf> = FxHashSet::default();
646	        let mut queue = std::collections::VecDeque::from([module.to_owned()]);
647	        while let Some(file) = queue.pop_front() {
648	            if seen.len() >= AUGMENTATION_SCAN_FILES {
649	                break;
650	            }
651	            if !seen.insert(file.clone()) || self.in_project(&file) || Self::is_react(&file) {
652	                continue;
653	            }
654	            let Some(data) = self.parse(&file) else { continue };
655	            let react_prefix = format!("{file}:React.");
656	            if data.interfaces.keys().any(|key| key.starts_with(&react_prefix)) {
657	                found.push(file.clone());
658	            }
659	            for export in &data.exports {
660	                let (LexedExport::ReExportNamed { source_specifier, .. }
661	                | LexedExport::ReExportAll { source_specifier, .. }
662	                | LexedExport::ReExportNamespace { source_specifier, .. }) = export
663	                else {
664	                    continue;
665	                };
666	                if let Ok(target) = self.resolve(&file, source_specifier) {
667	                    queue.push_back(target);
668	                }
669	            }
670	        }
671	        found.sort();
672	        let own = module.parent().and_then(|dir| self.package_of(dir));
673	        let mut crossed: Vec<PackageStampRow> = seen
674	            .iter()
675	            .filter_map(|file| self.package_of(file.parent()?))
676	            .filter(|package| Some(package) != own.as_ref())
677	            .collect::<FxHashSet<_>>()
678	            .into_iter()
679	            .filter_map(|package| {
680	                let (mtime_ns, size) = package_stamp(&package)?;
681	                Some((package.to_string(), mtime_ns, size))
682	            })
683	            .collect();
684	        crossed.sort();
685	        (found, crossed)
686	    }
687	
688	    /// Mark `(file, name)` loaded and follow the names its declaration references: same-file ones in place, imported
689	    /// ones as new demands. React's own declarations stay with the resolver's React handling (builtins, curated HTML
690	    /// attributes), so React's files never enter the layer, but what they import does: `CSSProperties` extends
691	    /// csstype's `Properties`.
692	    fn load_declaration<'s>(&'s self, scope: &rayon::Scope<'s>, file: Utf8PathBuf, name: CompactString) {
693	        if self.in_project(&file) {
694	            return;
695	        }
696	        let react = Self::is_react(&file);
697	        let Some(data) = self.parse(&file) else { return };
698	        // `Primitive.div` is a member of the value `Primitive`, whose declared type has it.
699	        let mut stack: Vec<CompactString> =
700	            name.split_once('.').map(|(head, _)| CompactString::from(head)).into_iter().collect();
701	        stack.push(name);
702	        while let Some(name) = stack.pop() {
703	            let claim = (PathKey::from(file.as_path()), name.clone());
704	            if self.parent.is_some_and(|parent| parent.has_claimed(&claim)) || !self.claimed.insert(claim) {
705	                continue;
706	            }
707	            if react {
708	                if !self.parent.is_some_and(|parent| parent.has_react_file(file.as_str())) {
709	                    self.react_files.insert(PathKey::from(file.as_path()));
710	                }
711	            } else if !self.parent.is_some_and(|parent| parent.is_dependency_file(&file)) {
712	                self.declaring.insert(PathKey::from(file.as_path()));
713	            }
714	            // The type a value is declared with (`declare const Primitive: Primitives`) goes with the value.
715	            let value_type = CompactString::from(format!("typeof {name}"));
716	            if declares(&data, &file, &value_type) {
717	                stack.push(value_type);
718	            }
719	            let mut refs = FxHashSet::default();
720	            declaration_refs(&data, &file, &name, &mut refs);
721	            for reference in refs {
722	                let qualified = react.then(|| CompactString::from(format!("React.{reference}")));
723	                if declares(&data, &file, &reference) {
724	                    stack.push(reference);
725	                } else if declares(&data, &file, &format!("typeof {reference}")) {
726	                    // `typeof NODES` names a value that has only its declared type.
727	                    stack.push(CompactString::from(format!("typeof {reference}")));
728	                } else if let Some(qualified) = qualified.filter(|q| declares(&data, &file, q)) {
729	                    stack.push(qualified);
730	                } else if let Some(demand) = imported_demand(&file, &data.imports, &reference) {
731	                    scope.spawn(move |scope| self.demand(scope, demand));
732	                }
733	            }
734	        }
735	    }
736	
737	    /// Note that an answer about `dir` is new, when `write_index` would keep it. A project file's own imports are
738	    /// resolved on every run and never reach the index, so they must not make a warm run rewrite it.
739	    fn learn(&self, dir: &Utf8Path) {
740	        if dir.as_str().contains("/node_modules/") && self.package_of(dir).is_some() {
741	            self.learned.store(true, Ordering::Relaxed);
742	        }
743	    }
744	
745	    fn package_of(&self, dir: &Utf8Path) -> Option<Box<str>> {
746	        if let Some(found) = self.packages.get(dir.as_str()) {
747	            return found.clone();
748	        }
749	        let found = dir
750	            .ancestors()
751	            .find(|candidate| candidate.join("package.json").is_file())
752	            .filter(|candidate| candidate.as_str().contains("/node_modules/"))
753	            .map(|candidate| Box::from(candidate.as_str()));
754	        self.packages.insert(Box::from(dir.as_str()), found.clone());
755	        found
756	    }
757	}
