759	/// Whether `file` declares `name` (an interface, type alias, enum, const array or component, possibly
760	/// namespace-qualified).
761	fn declares(data: &SourceData, file: &Utf8Path, name: &str) -> bool {
762	    let key = format!("{file}:{name}");
763	    data.interfaces.contains_key(&key)
764	        || data.type_aliases.contains_key(&key)
765	        || data.enums.contains_key(&key)
766	        || data.const_arrays.contains_key(&key)
767	        || data.component_mappings.iter().any(|m| m.component_name == name)
768	        // A constant declared by its type alone (`declare const Primitive: Primitives`).
769	        || data.type_aliases.contains_key(&format!("{file}:typeof {name}"))
770	}
771	
772	/// The names `(file, name)`'s declaration references, without its own type parameters.
773	fn declaration_refs(data: &SourceData, file: &Utf8Path, name: &str, out: &mut FxHashSet<CompactString>) {
774	    let key = format!("{file}:{name}");
775	    if let Some(iface) = data.interfaces.get(&key) {
776	        interface_refs(iface, out);
777	    }
778	    if let Some(alias) = data.type_aliases.get(&key) {
779	        alias_refs(alias, out);
780	    }
781	    for mapping in data.component_mappings.iter().filter(|m| m.component_name == name) {
782	        mapping_refs(mapping, out);
783	    }
784	    // A reference that omits an argument reads the default (`DOMAttributes<T = FocusableElement>`).
785	    for default in data.type_param_defaults.get(&key).into_iter().flatten().flatten() {
786	        type_refs(default, out);
787	    }
788	    for params in [data.interface_type_params.get(&key), data.type_alias_params.get(&key)].into_iter().flatten() {
789	        for param in params {
790	            out.remove(param.as_str());
791	        }
792	    }
793	}
