#[test]
fn tmp_prefilters_over_a_real_tree() {
    let Some(root) = std::env::var_os("TMP_TREE") else { return };
    let mut stack = vec![std::path::PathBuf::from(root)];
    let (mut files, mut react_true, mut react_needed, mut re_true, mut re_needed, mut bad) = (0, 0, 0, 0, 0, 0);
    while let Some(dir) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&dir) else { continue };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            let name = path.to_string_lossy().to_string();
            if !(name.ends_with(".d.ts") || name.ends_with(".d.mts") || name.ends_with(".d.cts")) {
                continue;
            }
            let Ok(source) = std::fs::read_to_string(&path) else { continue };
            let data = crate::extractor::parse_file(Utf8Path::new(&name), &source);
            let (_, specifiers) = scan_of(&data, Utf8Path::new(&name));
            let augments = data.interfaces.keys().any(|k| k.contains(":React."));
            files += 1;
            let (r, e) = (may_declare_into_react(&source), may_re_export(&source));
            react_true += usize::from(r);
            re_true += usize::from(e);
            react_needed += usize::from(augments);
            re_needed += usize::from(!specifiers.is_empty());
            if (augments && !r) || (!specifiers.is_empty() && !e) {
                bad += 1;
                eprintln!("FALSE NEGATIVE {name} augments={augments} r={r} specifiers={} e={e}", specifiers.len());
            }
        }
    }
    eprintln!("PREFILTERS files={files} may_declare={react_true} (needed {react_needed}) may_re_export={re_true} (needed {re_needed}) false_negatives={bad}");
    assert_eq!(bad, 0);
}
